fileprivate struct UniffiCallbackInterfaceMeasure {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceMeasure = UniffiVTableCallbackInterfaceMeasure(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeMeasure.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface Measure: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeMeasure.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface Measure: handle missing in uniffiClone")
            }
        },
        measure: { (
            uniffiHandle: UInt64,
            call: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> FfiSize in
                guard let uniffiObj = try? FfiConverterTypeMeasure.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.measure(
                     call: try FfiConverterTypeMeasureCall_lift(call)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeFfiSize_lower($0) }
