public struct FfiConverterTypeAvailMode: FfiConverterRustBuffer {
    typealias SwiftType = AvailMode

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AvailMode {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .definite
        
        case 2: return .minContent
        
        case 3: return .maxContent
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AvailMode, into buf: inout [UInt8]) {
        switch value {
        
        
        case .definite:
            writeInt(&buf, Int32(1))
        
        
        case .minContent:
            writeInt(&buf, Int32(2))
        
        
        case .maxContent:
            writeInt(&buf, Int32(3))
        
        }
    }
}


