public struct FfiConverterTypeVappError: FfiConverterRustBuffer {
    typealias SwiftType = VappError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VappError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Invalid(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VappError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Invalid(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


