/**
 * A synthetic ~n-node surface for the timing measurement.
 */
public func benchTreeJson(n: UInt32) -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_vapp_spike_ffi_fn_func_bench_tree_json(
        FfiConverterUInt32.lower(n),uniffiCallStatus
    )
})
}
/**
 * The fixed-measure intrinsic size of a leaf, so a host can run the
 * geometry-mode comparison without its own text engine.
 */
public func fixedIntrinsic(kind: String, propsJson: String) -> FfiSize  {
    return try!  FfiConverterTypeFfiSize_lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_vapp_spike_ffi_fn_func_fixed_intrinsic(
        FfiConverterString.lower(kind),
        FfiConverterString.lower(propsJson),uniffiCallStatus
    )
})
}
