private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_vapp_spike_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_func_bench_tree_json() != 51498) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_func_fixed_intrinsic() != 50865) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_func_kitchen_sink_json() != 51534) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_measure_measure() != 50613) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_build_ns() != 42932) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_invalidate_measures() != 48656) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_layout() != 48949) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_layout_fixed() != 32062) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_mark_dirty() != 18289) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_node_count() != 28770) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_nodes() != 6524) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_set_pressed() != 40243) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_set_rounding() != 33655) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_method_surface_set_viewport() != 31369) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vapp_spike_ffi_checksum_constructor_surface_new() != 60219) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitMeasure()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureVappSpikeFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

